// Small-stencil physical P5 hypothesis falsifier; no production adoption.
#define main transition_reference_not_invoked
#include "diagnose_transition_jets.cpp"
#undef main
#include "transition_polynomial_jet.hpp"
using Fit=h::TransitionPolynomialJet;
Real LocalH(const Grid&g,size_t p){Real biggest=0;for(int A=0;A<3;++A){Real norm=0;for(int a=0;a<3;++a)norm+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];biggest=std::max(biggest,std::sqrt(norm));}return 1/(g.n*biggest);}
WeightAudit Bound(const Fit&fit,int count,Real dx,const h::PuncturePosition&position){WeightAudit out;Real gradient[3]{},hessian[3][3]{};for(int i=0;i<count;++i){V impulse(count,0);impulse[i]=1;Fit::Result r;if(!fit.Evaluate(impulse,position,r))throw std::runtime_error("impulse failed");out.value+=std::abs(r.fitted_value);for(int a=0;a<3;++a){gradient[a]+=dx*std::abs(r.gradient[a]);for(int b=0;b<3;++b)hessian[a][b]+=dx*dx*std::abs(r.hessian[a][b]);}}for(int a=0;a<3;++a){out.gradient=std::max(out.gradient,gradient[a]);for(int b=0;b<3;++b)out.hessian=std::max(out.hessian,hessian[a][b]);}return out;}
S Fitted(const Fit&fit,const V&v,Real value,const h::PuncturePosition&position){Fit::Result r;if(!fit.Evaluate(v,position,r))throw std::runtime_error("valid scalar fit failed");S q{};q.value=value;for(int a=0;a<3;++a){q.d[a]=r.gradient[a];for(int b=0;b<3;++b)q.dd[a][b]=r.hessian[a][b];}return q;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=3)throw std::runtime_error("initial.dat exact.dat");const auto start=std::chrono::steady_clock::now();const auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);const auto exact=ReadExact(argv[2]);h::PuncturePosition position;std::cout<<std::setprecision(17);std::vector<size_t>targets{126};for(int face=0;face<6;++face)for(int i:{0})for(int j:{0,2,3,5})for(int k:{0,3}){const size_t p=((face*6+k)*6+j)*6+i;if(std::find(targets.begin(),targets.end(),p)==targets.end())targets.push_back(p);}if(targets.size()>145)throw std::runtime_error("target budget");
 size_t accepted=0,rejected=0;Real maxcondition=0,maxrepro=0,maxnoise=0,maxmoment=0;for(size_t p:targets){const auto &x=grid.geometry[p].x;const Real dx=LocalH(grid,p);std::vector<std::pair<Real,size_t>>near;for(size_t q=0;q<grid.active.size();++q){Real d=0;for(int a=0;a<3;++a)d+=std::pow(grid.geometry[q].x[a]-x[a],2);near.push_back({d,q});}std::partial_sort(near.begin(),near.begin()+256,near.end());
 for(int count:{125,175,256}){std::vector<Fit::Point>points;for(int i=0;i<count;++i){const auto&y=grid.geometry[near[i].second].x;points.push_back({y[0],y[1],y[2]});}Fit fit;Fit::Options options;options.maximum_condition=1e8;options.maximum_scaled_weight_l1=64;const bool built=fit.Build({x[0],x[1],x[2]},points,dx,position,options);WeightAudit bound;bool valid=built;if(valid){bound=Bound(fit,count,dx,position);valid=bound.value<=16&&bound.gradient<=32&&bound.hessian<=64&&fit.diagnostics().reproduction<=1e-10;}const auto &d=fit.diagnostics();std::cout<<"{\"phase\":\"plan\",\"point\":"<<p<<",\"donors\":"<<count<<",\"rank\":"<<d.rank<<",\"status\":\""<<(valid?"ready":(built?"functional_or_reproduction_guard":d.status))<<"\",\"condition\":"<<d.condition<<",\"reproduction\":"<<d.reproduction<<",\"value_l1\":"<<bound.value<<",\"gradient_l1\":"<<bound.gradient<<",\"hessian_l1\":"<<bound.hessian<<"}\n";if(!valid){++rejected;continue;}++accepted;maxcondition=std::max(maxcondition,d.condition);maxrepro=std::max(maxrepro,d.reproduction);
  // Independent physical constants/anisotropic affine/quadratic moments. The
  // fitted value is never installed into any physical field.
  for(int mode=0;mode<3;++mode){V values;for(const auto&y:points)values.push_back(mode==0?1:(mode==1?y[0]+.3*y[1]-.7*y[2]:y[0]*y[0]+.7*y[0]*y[1]-.2*y[1]*y[2]+2*y[2]*y[2]));const auto r=Fitted(fit,values,0,position);S e{};if(mode==1){e.d[0]=1;e.d[1]=.3;e.d[2]=-.7;}if(mode==2){e.d[0]=2*x[0]+.7*x[1];e.d[1]=.7*x[0]-.2*x[2];e.d[2]=4*x[2]-.2*x[1];e.dd[0][0]=2;e.dd[2][2]=4;e.dd[0][1]=e.dd[1][0]=.7;e.dd[1][2]=e.dd[2][1]=-.2;}for(int a=0;a<3;++a){maxmoment=std::max(maxmoment,std::abs(r.d[a]-e.d[a]));for(int b=0;b<3;++b)maxmoment=std::max(maxmoment,std::abs(r.dd[a][b]-e.dd[a][b]));}}
  for(int field=0;field<2;++field)for(int angular=0;angular<2;++angular)for(int storage=0;storage<2;++storage){V values;for(int i=0;i<count;++i){const size_t q=near[i].second;const auto&y=grid.geometry[q].x;Real v=field==0?std::log(initial[q].chi):std::log(initial[q].alpha/((1+initial[q].r*initial[q].r)/2));if(angular)v+=1e-3*y[0]*y[1]/(initial[q].r*initial[q].r);if(storage)v=std::exp(v)*(field==1?(1+initial[q].r*initial[q].r)/2:1);values.push_back(v);}S truth=StoredExact(x,exact.at({0,p}),field);if(angular){cubed_sphere::Jet y[3];for(int a=0;a<3;++a)y[a]=cubed_sphere::Jet::Variable(x[a],a);const auto pert=cubed_sphere::Jet(.001)*y[0]*y[1]/(y[0]*y[0]+y[1]*y[1]+y[2]*y[2]);truth.value+=pert.f;for(int a=0;a<3;++a){truth.d[a]+=pert.d[a];for(int b=0;b<3;++b)truth.dd[a][b]+=pert.h[a][b];}}
   S analytic{};if(Chart(x,field).Reconstruct(truth,analytic)!=h::PositiveFieldStatus::valid)throw std::runtime_error("P5 analytic reconstruction failed");const S fitted=Fitted(fit,values,storage?analytic.value:truth.value,position);S physical{};if(storage)physical=fitted;else if(Chart(x,field).Reconstruct(fitted,physical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("P5 positive jet reconstruction failed");Real dg=0,dd=0;for(int a=0;a<3;++a){dg=std::max(dg,std::abs(physical.d[a]-analytic.d[a]));for(int b=0;b<3;++b)dd=std::max(dd,std::abs(physical.dd[a][b]-analytic.dd[a][b]));}
   V noise=values;for(int i=0;i<count;++i)noise[i]+=1e-12*(std::sin(1.7*i)+std::cos(.9*i))/2;const auto nq=Fitted(fit,noise,truth.value,position);Real ns=0;for(int a=0;a<3;++a){ns=std::max(ns,dx*std::abs(nq.d[a]-fitted.d[a]));for(int b=0;b<3;++b)ns=std::max(ns,dx*dx*std::abs(nq.dd[a][b]-fitted.dd[a][b]));}maxnoise=std::max(maxnoise,ns);if(ns>std::max(bound.gradient,bound.hessian)*1e-12+2e-13)throw std::runtime_error("noise functional bound failed");auto u=Analytic({x[0],x[1],x[2]},exact.at({0,p}));if(field==0)u.chi=physical;else u.alpha=physical;const auto v=h::EvolvedConstraints(u,h::CompositeOmegaAt(x,u));if(!v.valid)throw std::runtime_error("invalid P5 constraint");auto ue=Analytic({x[0],x[1],x[2]},exact.at({0,p}));if(field==0)ue.chi=analytic;else ue.alpha=analytic;const auto ve=h::EvolvedConstraints(ue,h::CompositeOmegaAt(x,ue));std::cout<<"{\"phase\":\"scalar\",\"point\":"<<p<<",\"donors\":"<<count<<",\"field\":\""<<(field==0?"chi":"alpha")<<"\",\"storage\":\""<<(storage?"direct_physical":"positive_log")<<"\",\"angular\":"<<angular<<",\"gradient_error\":"<<dg<<",\"hessian_error\":"<<dd<<",\"H\":"<<v.hamiltonian<<",\"H_error\":"<<v.hamiltonian-ve.hamiltonian<<",\"scaled_noise\":"<<ns<<",\"active_value_changed\":false}\n";
  }
 }
 }
 std::cout<<"{\"phase\":\"summary\",\"targets\":"<<targets.size()<<",\"plans_ready\":"<<accepted<<",\"plans_rejected\":"<<rejected<<",\"maximum_condition\":"<<maxcondition<<",\"maximum_reproduction\":"<<maxrepro<<",\"physical_constant_linear_quadratic_error_max\":"<<maxmoment<<",\"maximum_scaled_noise\":"<<maxnoise<<",\"all56columns_retained\":true,\"guards_16_32_64\":true,\"production_adopted\":false,\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
